    private static TextureAtlasSprite getConnectedTextureRepeat(ConnectedProperties cp, BlockPos blockPos, int side)
    {
        if (cp.tileIcons.length == 1)
        {
            return cp.tileIcons[0];
        }
        else
        {
            int i = blockPos.getX();
            int j = blockPos.getY();
            int k = blockPos.getZ();
            int l = 0;
            int i1 = 0;

            switch (side)
            {
                case 0:
                    l = i;
                    i1 = -k - 1;
                    break;

                case 1:
                    l = i;
                    i1 = k;
                    break;

                case 2:
                    l = -i - 1;
                    i1 = -j;
                    break;

                case 3:
                    l = i;
                    i1 = -j;
                    break;

                case 4:
                    l = k;
                    i1 = -j;
                    break;

                case 5:
                    l = -k - 1;
                    i1 = -j;
            }

            l = l % cp.width;
            i1 = i1 % cp.height;

            if (l < 0)
            {
                l += cp.width;
            }

            if (i1 < 0)
            {
                i1 += cp.height;
            }

            int j1 = i1 * cp.width + l;
            return cp.tileIcons[j1];
        }
    }

