    {
        if (blockAccess.getBlockState(pos.offset(side)).getMaterial() == this.material)
        {
            return false;
        }
        else
        {
            return side == EnumFacing.UP || super.shouldSideBeRendered(blockState, blockAccess, pos, side);
        }
