     */
    public int tickRate(World worldIn)
    {
        if (this.material == Material.WATER)
        {
            return 5;
        }
        else if (this.material == Material.LAVA)
        {
            return worldIn.provider.isNether() ? 10 : 30;
        }
        else
        {
            return 0;
        }
    }

