    {
        if (this.countResetDisplayList != Shaders.countResetDisplayLists)
        {
            this.compiled = false;
            this.countResetDisplayList = Shaders.countResetDisplayLists;
        }
    }

    public ResourceLocation getTextureLocation()
    {
        return this.textureLocation;
    }

