            for (BlockRenderLayer blockrenderlayer1 : ENUM_WORLD_BLOCK_LAYERS) {
                if (aboolean[blockrenderlayer1.ordinal()]) {
                    compiledchunk.setLayerUsed(blockrenderlayer1);
                }

                if (compiledchunk.isLayerStarted(blockrenderlayer1)) {
                    if (Config.isShaders()) {
