				.setTargetIds(Collections.singleton(construct.getId().toString()))
				.setIds(new HashSet<>(Arrays.asList(node1.getId(), node2.getId())));

		// link it
		GenericResponse updated = supply(() -> new ConstructResourceImpl().link(link));
