public class Ring extends KindofMisc {

	protected Buff buff;

	private static final LinkedHashMap<String, Asset> gems = new LinkedHashMap<String, Asset>() {
		{
			put("garnet",GeneralAsset.RING_GARNET);
			put("ruby",GeneralAsset.RING_RUBY);
			put("topaz",GeneralAsset.RING_TOPAZ);
			put("emerald",GeneralAsset.RING_EMERALD);
			put("onyx",GeneralAsset.RING_ONYX);
			put("opal",GeneralAsset.RING_OPAL);
			put("tourmaline",GeneralAsset.RING_TOURMALINE);
			put("sapphire",GeneralAsset.RING_SAPPHIRE);
			put("amethyst",GeneralAsset.RING_AMETHYST);
			put("quartz",GeneralAsset.RING_QUARTZ);
			put("agate",GeneralAsset.RING_AGATE);
			put("diamond",GeneralAsset.RING_DIAMOND);
		}
	};

	private static ItemStatusHandler<Ring> handler;

	private String gem;

	//rings cannot be 'used' like other equipment, so they ID purely based on exp
	private float levelsToID = 1;

	@SuppressWarnings("unchecked")
	public static void initGems() {
		handler = new ItemStatusHandler<>( (Class<? extends Ring>[])Generator.Category.RING.classes, gems );
	}

	public static void save( Bundle bundle ) {
		handler.save( bundle );
	}

	public static void saveSelectively( Bundle bundle, ArrayList<Item> items ) {
		handler.saveSelectively( bundle, items );
	}

	@SuppressWarnings("unchecked")
	public static void restore( Bundle bundle ) {
		handler = new ItemStatusHandler<>( (Class<? extends Ring>[])Generator.Category.RING.classes, gems, bundle );
	}

	public Ring() {
		super();
		reset();
	}

	//anonymous rings are always IDed, do not affect ID status,
	//and their sprite is replaced by a placeholder if they are not known,
	//useful for items that appear in UIs, or which are only spawned for their effects
	protected boolean anonymous = false;
	public void anonymize(){
		if (!isKnown()) image = GeneralAsset.RING_HOLDER;
		anonymous = true;
	}

	public void reset() {
		super.reset();
		levelsToID = 1;
		if (handler != null && handler.contains(this)){
			image = handler.image(this);
			gem = handler.label(this);
		}
	}

	public void activate( Char ch ) {
		if (buff != null){
			buff.detach();
			buff = null;
		}
		buff = buff();
		buff.attachTo( ch );
	}

	@Override
	public boolean doUnequip( Hero hero, boolean collect, boolean single ) {
		if (super.doUnequip( hero, collect, single )) {

			if (buff != null) {
				buff.detach();
				buff = null;
			}

			return true;

		} else {

			return false;

		}
	}

	public boolean isKnown() {
		return anonymous || (handler != null && handler.isKnown( this ));
	}

	public void setKnown() {
		if (!anonymous) {
			if (!isKnown()) {
				handler.know(this);
			}

			if (Dungeon.hero.isAlive()) {
				Catalog.setSeen(getClass());
			}
		}
	}

	@Override
	public String name() {
		return isKnown() ? super.name() : Messages.get(Ring.class, gem);
	}

	@Override
	public String info(){

		String desc = isKnown() ? super.desc() : Messages.get(this, "unknown_desc");

		if (cursed && isEquipped( Dungeon.hero )) {
			desc += "\n\n" + Messages.get(Ring.class, "cursed_worn");

		} else if (cursed && cursedKnown) {
			desc += "\n\n" + Messages.get(Ring.class, "curse_known");

		} else if (!isIdentified() && cursedKnown){
			desc += "\n\n" + Messages.get(Ring.class, "not_cursed");

		}

		if (isKnown()) {
			desc += "\n\n" + statsInfo();
		}

		return desc;
	}

	protected String statsInfo(){
		return "";
	}

	@Override
	public Item upgrade() {
		super.upgrade();

		if (Random.Int(3) == 0) {
			cursed = false;
		}

		return this;
	}

	@Override
	public boolean isIdentified() {
		return super.isIdentified() && isKnown();
	}

	@Override
	public Item identify( boolean byHero ) {
		setKnown();
		levelsToID = 0;
		return super.identify(byHero);
	}

	@Override

