						String thisEntry = iter1.next();

						if (lastEntry != null && lastEntry.equals(thisEntry)) {
							// when there is a last entry and it equals this
							// entry, remove this entry
							iter1.remove();
						} else {
							// we have a new last entry
							lastEntry = thisEntry;
						}
					}

