				CMSUnavailableException {
		boolean isMulti = DatatypeHelper.isMultivalue(handle, name);

		if (isMulti) {
			GenticsContentAttribute attr = (GenticsContentAttribute) m_attributeHash.get(name);

			attr.setNeedsSortorderFixed();
		}
