    private int calculateParticleLevel(boolean minimiseLevel) {
        int k1 = this.mc.gameSettings.particleSetting;

        if (minimiseLevel && k1 == 2 && this.world.rand.nextInt(10) == 0) {
            k1 = 1;
        }

        if (k1 == 1 && this.world.rand.nextInt(3) == 0) {
            k1 = 2;
        }

        return k1;
    }

