					protected void select( boolean value ) {
						super.select( value );
						loreTab.active = loreTab.visible = value;
						if (value) last_index = 4;
					}
				}
		};

		for (Tab tab : tabs) {
			add( tab );
		}

		layoutTabs();

		select(last_index);
	}

