		CNDatasource ds = (CNDatasource) attribute.getParent().getDatasource();

		try {
			return getInputStream(ds.getHandle().getDBHandle(), basePath, null);
		} catch (CMSUnavailableException e) {
			throw new IOException(e);
		}
	}

