     * fail, null is returned.
     */
    public static Item getByNameOrId(String id)
    {
        Item item = REGISTRY.getObject(new ResourceLocation(id));

        if (item == null)
        {
            try
            {
                return getItemById(Integer.parseInt(id));
            }
            catch (NumberFormatException var3)
            {
            }
        }

        return item;
    }

