				if (!batch) {
					ds.insert(Collections.singleton(changeable));
				}
				objects.add(changeable);
			}
		}
		if (batch) {
			ds.insert(objects);
		}

		ds.clearCaches();

		// check whether the objects were correctly inserted
		for (int channelId = 1; channelId <= 3; channelId++) {
			ds.setChannel(channelId);
