			if (!batch) {
				ds.update(Collections.singleton(changeable));
			}
		}

		if (batch) {
			ds.update(objects);
		}
		ds.clearCaches();

		// do another update
		for (Changeable changeable : objects) {
			updateObject(changeable,  null, 0, 0, null, null, null);
			if (!batch) {
				ds.update(Collections.singleton(changeable));
			}
		}

		if (batch) {
			ds.update(objects);
		}
	}

