				this.modified = true;
				this.dpiX = dpiX;
				return oldDpiX;
			} else {
				return this.dpiX;
			}
		}

		/*
		 * (non-Javadoc)
		 * @see com.gentics.contentnode.object.ContentFile#setDpiY(int)
		 */
		public int setDpiY(int dpiY) throws ReadOnlyException {
			assertEditable();
			// Check if dpiX has changed
			if (!(dpiY == this.dpiY)) {
				int oldDpiY = this.dpiY;

				this.modified = true;
				this.dpiY = dpiY;
				return oldDpiY;
			} else {
				return this.dpiY;
			}
		}


