				}
			}
		}

		// set the updatetimestamp to the channel
		if (isUpdateTimestampOnWrite() && deleteCount > 0) {
			for (Integer channelId : updatedChannels) {
				setLastUpdate(channelId);
			}
		}

		return new NumDatasourceInfo(deleteCount);
	}

