	public void reset( int type, PointF from, PointF to, Callback callback ) {
		this.callback = callback;

		this.to = to;

		x = from.x;
		y = from.y;
		width = 0;
		height = 0;

		PointF d = PointF.diff( to, from );
		PointF speed = new PointF( d ).normalize().scale( SPEED );
		sx = speed.x;
		sy = speed.y;
		time = d.length() / SPEED;

		switch(type){
			case MAGIC_MISSILE: default:
