		contenttagVersion.restoreVersion(contentId, timestamp);
		valueVersion.restoreVersion(contentId, timestamp);
		dsVersion.restoreVersion(contentId, timestamp);
		dsObjVersion.restoreVersion(contentId, timestamp);
	}

