            i = 60;
            j = 3;
        }
        else if (item == Items.GOLDEN_CARROT)
        {
            f = 4.0F;
            i = 60;
            j = 5;

            if (this.isTame() && this.getGrowingAge() == 0 && !this.isInLove())
            {
