	 * Synchronize to the filesystem
	 * @param folder target folder
	 * @throws NodeException
	 */
	public void syncToFilesystem(Path folder) throws NodeException {
		T object = findObject(folder);
		if (object == null) {
			return;
		}

		syncToFilesystem(object, folder);
	}

