            value |= 8192;
        }

        map.put("minecraft:" + name, Integer.valueOf(value));

        if (extended)
        {
            int i = value | 32;
            map.put("minecraft:strong_" + name, Integer.valueOf(i));
            int j = value | 64;
            map.put("minecraft:long_" + name, Integer.valueOf(j));
        }
    }

