	 */
	public static final int STATUS_UNKOWN = -1;

	/**
	 * The system is waiting for a new job
	 */
	public static final int STATUS_PENDING = 0;

	/**
	 * A job is currently being processed
	 */
	public static final int STATUS_IN_PROGRESS = 1;

