				pageListParams,
				new LegacyFilterParameterBean(),
				new LegacySortParameterBean(),
				new LegacyPagingParameterBean(),
				new PublishableParameterBean(),
				wastebinParams);

			ContentNodeRESTUtils.assertResponseOK(legacyResponse);

			return legacyResponse.getPages();
