	private void setMapStart(){
		transitions.add(new LevelTransition(this, ENTRANCE_POS, LevelTransition.Type.REGULAR_ENTRANCE, 0));

		Painter.fill(this, 0, 0, 32, 32, Terrain.WALL);

		//Start
