					sql.append(")");

					sql.append(" AND content.id IS NOT NULL AND template.id IS NOT NULL");

					SystemUser user = (SystemUser) t.getObject(SystemUser.class, t.getUserId());
					Integer userId = null;
					List<UserGroup> userGroups = Collections.emptyList();

					if (user != null) {
