				sorting,
				paging,
				publishParams,
				wastebinParams);

			ContentNodeTestUtils.assertResponseCodeOk(legacyResponse);
			assertEquals(2 * count, legacyResponse.getNumItems().intValue());
		}

		// Revoke the permission on the subfolder
		try (Trx tx = new Trx(null, 1)) {
