		if (!keyword.startsWith("object.")) {
			keyword = "object." + keyword;
		}
		objectTag.setName(keyword);
		objectTag.setObjType(type);
		objProp.save();
		t.commit(false);

		return t.getObject(ObjectTagDefinition.class, objProp.getId());
