			List<PublishObjectTask> publishFolderObjectTaskQueue, List<PublishObjectTask> publishFileObjectTaskQueue) {
		this(config, publishInfo);
		this.publishFolderObjectTaskQueue = publishFolderObjectTaskQueue;
