            {
                NonNullList<ItemStack> nonnulllist = NonNullList.create();

                for (int i = 0; i < this.player.openContainer.inventorySlots.size(); ++i)
                {
                    nonnulllist.add(this.player.openContainer.inventorySlots.get(i).getStack());
