                if (networkplayerinfo != null) {
                    switch (packetIn.getAction()) {
                        case ADD_PLAYER:
                            networkplayerinfo.setGameType(playerData.getGameMode());
                            networkplayerinfo.setResponseTime(playerData.getPing());
                            break;

                        case UPDATE_GAME_MODE:
                            networkplayerinfo.setGameType(playerData.getGameMode());
                            break;

                        case UPDATE_LATENCY:
                            networkplayerinfo.setResponseTime(playerData.getPing());
                            break;

                        case UPDATE_DISPLAY_NAME:
